public class MockitoDependencyNote {
    public static void main(String[] args) {
        System.out.println("This exercise is a pom.xml fragment, not Java source.");
        System.out.println("It declares the Mockito dependency used to mock TemperatureSensor:");
        System.out.println("  groupId    : org.mockito");
        System.out.println("  artifactId : mockito-core");
        System.out.println("  version    : 5.12.0");
        System.out.println("  scope      : test");
        System.out.println();
        System.out.println("Maven reads this block and downloads the library for the test classpath.");
    }
}
